#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;

    #[test]
    fn test_sp_wp_lifecycle() {
        let dummy = RemoteBinder::new(10, 0x1234);
        assert_eq!(dummy.handle(), Some(10));
        assert!(dummy.is_binder_alive());

        let weak = dummy.downgrade();
        let strong = weak.upgrade().expect("Upgrade should succeed");
        assert_eq!(strong.handle(), Some(10));
    }

    #[test]
    fn test_death_recipient_lifecycle() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        let death_count = Arc::new(AtomicUsize::new(0));
        let dc_clone = Arc::clone(&death_count);

        let recipient: Arc<dyn DeathRecipient> = Arc::new(DeathCallback(move || {
            dc_clone.fetch_add(1, Ordering::SeqCst);
        }));

        let registry = DeathRecipientRegistry::new();
        assert_eq!(registry.recipient_count(), 0);

        registry.link(Arc::clone(&recipient), true).unwrap();
        assert_eq!(registry.recipient_count(), 1);

        // Unlink
        registry.unlink(&recipient).unwrap();
        assert_eq!(registry.recipient_count(), 0);

        // Link again and trigger death
        registry.link(recipient, true).unwrap();
        registry.notify_death();
        assert_eq!(death_count.load(Ordering::SeqCst), 1);
        assert_eq!(registry.recipient_count(), 0);
    }
}
